 if len(sys.argv)==1:obs()
 elif sys.argv[1]=='move':
  o=pickle.load(open(f'{OUT}/latest.pkl','rb'));q=target(o); changes=json.loads(sys.argv[2]);
  for k,v in changes.items():q[int(k)]=v
